-- Question layer for the Responsa collection (/responsa/questions).
-- A question can now carry answers from several rabbis (the Kiddush
-- question, Nov 2026: nine respondents, one question). Rabbi pages keep
-- working as before; each responsa row links to its question where one exists.
-- Seed: the Kiddush question + 9 answers, from
-- Kiddush-question-and-responses-af91e2b1_2_85jq.pdf (PDF export 18 Nov 2026,
-- correspondence 1-4 Nov 2026). Verbatim vs summary status is per-row in `note`.

create table if not exists public.responsa_questions (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  title text not null,
  title_he text,
  question_text text not null,
  question_lang text not null default 'en' check (question_lang in ('he', 'en')),
  question_date date,
  note text,
  tags text[] not null default '{}',
  status text not null default 'published' check (status in ('draft', 'published')),
  created_at timestamptz not null default now()
);

alter table public.responsa add column if not exists question_id uuid references public.responsa_questions(id) on delete set null;
create index if not exists responsa_question_idx on public.responsa (question_id, position);

alter table public.responsa_questions enable row level security;
drop policy if exists "read published responsa questions" on public.responsa_questions;
create policy "read published responsa questions" on public.responsa_questions
  for select to anon, authenticated using (status = 'published');

