insert into public.responsa_questions (slug, title, question_text, question_lang, question_date, note, tags, status) values ('making-up-friday-night-kiddush-at-shabbat-lunch', 'Making up Friday-night kiddush at Shabbat lunch', 'I understand from Shulchan Aruch OC 271:8 and the Rema that someone who missed Friday-night kiddush says the full nighttime kiddush during the day, except Vayechulu. I saw a kiruv rabbi make the nighttime kiddush at Shabbat lunch for students who hadn''t heard it Friday night. Is that correct, including if the rabbi already fulfilled his own obligation, and why is this practice so rarely seen?', 'en', '2026-11-01', 'Source: Shulchan Aruch, Orach Chayim 271:8 with the Rema (Sefaria). “אם לא קידש בלילה, בין בשוגג בין במזיד, יש לו תשלומין למחר כל היום” — “If he didn''t make kiddush at night, whether inadvertently or deliberately, he can make it up throughout the following day.” Correspondence collected 1–4 November 2026. Summaries and selected quotations retain each respondent''s qualifications; these answers are not merged into one ruling. Awaiting replies (sent 1 Nov 2026): Rabbi Prof. David Golinkin (Schechter Institutes), Rabbi Chaim Jachter (Teaneck), Dayan Reiss (cRc Chicago).', array['kiddush', 'shabbat', 'tashlumin']::text[], 'published') on conflict (slug) do update set title = excluded.title, question_text = excluded.question_text, question_lang = excluded.question_lang, question_date = excluded.question_date, note = excluded.note, tags = excluded.tags, status = excluded.status;

